window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[332]={"id":"332","numero":332,"titre":"États de choc","objectifs":[{"id":"332-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de l’état de choc","contenu":"<p>L'<span class=\"kw-alerte\">état de choc</span> est une <span class=\"kw-def\">insuffisance circulatoire aiguë</span> altérant de façon <strong>durable</strong> l'<span class=\"kw-def\">oxygénation</span> et le <span class=\"kw-def\">métabolisme</span> des tissus et des organes. La notion de <strong><span class=\"kw-alerte\">souffrance d'organe</span></strong> est centrale : c'est elle qui distingue l'<span class=\"kw-alerte\">état de choc</span> du simple collapsus.</p>\n      <div class=\"callout callout-info\">\n        <strong><span class=\"kw-alerte\">Choc</span> <span class=\"kw-bio\">vs</span> collapsus.</strong> Le <span class=\"kw-def\">collapsus</span> est une <span class=\"kw-def\">défaillance hémodynamique sans atteinte de l'oxygénation tissulaire</span>. Il peut néanmoins aboutir à un <span class=\"kw-alerte\">état de choc</span> en conduisant à une inadéquation entre <span class=\"kw-clinique\">les</span> apports et les besoins en oxygène.\n      </div>\n      <p>Au-delà de l'insuffisance circulatoire, deux mécanismes sont impliqués précocement :</p>\n      <ul>\n        <li><strong>Système immunitaire inné</strong> — <span class=\"kw-def\">orage cytokinique</span>, réaction pro- et anti-<span class=\"kw-etio\">inflammatoire</span> simultanée.</li>\n        <li><strong>Voies métaboliques</strong> — plusieurs voies touchées, dont la <span class=\"kw-def\">dysfonction mitochondriale</span>.</li>\n      </ul>\n      <p>Insuffisance circulatoire, anomalies de l'inflammation et dysfonctions métaboliques sont déclenchées différemment selon le type de <span class=\"kw-alerte\">choc</span>, mais finissent par s'associer et entraîner la <strong>dysfonction progressive de tous <span class=\"kw-clinique\">les</span> organes</strong>.</p>\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">Urgence</span>.</strong> En l'absence de prise en charge, l'<span class=\"kw-alerte\">état de choc</span> évolue vers le <span class=\"kw-alerte\">syndrome de défaillance multiviscérale</span> (SDMV) puis le <span class=\"kw-alerte\">décès</span>.\n      </div>","frequence":0},{"id":"332-2","rang":"A","rubrique":"Étiologies","titre":"Connaître les principales étiologies des états de choc","contenu":"<p><span class=\"kw-clinique\">Les</span> états de <span class=\"kw-alerte\">choc</span> se classent selon leur <span class=\"kw-def\">mécanisme physiopathologique</span> dominant : chocs <strong>quantitatifs</strong> (baisse du transport en O₂), <strong>distributifs</strong> (baisse de l'extraction de l'O₂) et <strong>obstructif</strong> (obstacle mécanique).</p>\n      <table >\n        <thead><tr><th>Type de choc</th><th>Catégorie</th><th>Principales étiologies</th></tr></thead>\n        <tbody>\n          <tr>\n            <th>Hypovolémique (dont <span class=\"kw-etio\">hémorragique</span>)</th>\n            <td>Quantitatif</td>\n            <td><strong>Hypovolémie absolue :</strong> pertes sanguines ; pertes plasmatiques ; défaut d'hydratation<br><strong>Hypovolémie relative :</strong> fuite plasmatique vers l'interstitium</td>\n          </tr>\n          <tr>\n            <th>Cardiogénique</th>\n            <td>Quantitatif</td>\n            <td><strong>Atteinte du myocarde :</strong> ischémie (<span class=\"kw-def\">SCA</span>) ; myocardite<br><strong>Obstacle / remplissage :</strong> ↑ post-charge VD ou VG ; défaut de remplissage ventriculaire</td>\n          </tr>\n          <tr>\n            <th>Obstructif</th>\n            <td>Obstructif</td>\n            <td><span class=\"kw-def\">Embolie pulmonaire</span> ; <span class=\"kw-alerte\">tamponnade</span> ; <span class=\"kw-imagerie\">pneumothorax</span> compressif</td>\n          </tr>\n          <tr>\n            <th>Septique</th>\n            <td>Distributif</td>\n            <td><span class=\"kw-def\">Sepsis</span> — type même du <span class=\"kw-alerte\">choc</span> distributif</td>\n          </tr>\n          <tr>\n            <th>Anaphylactique</th>\n            <td>Distributif</td>\n            <td>Réaction <span class=\"kw-etio\">allergique</span> grave (médicament, aliment, venin d'hyménoptère)</td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-etio\">Inflammatoire</span></th>\n            <td>Distributif</td>\n            <td>Pancréatite ; <span class=\"kw-ttt\">chirurgie</span> lourde ; ischémie-<span class=\"kw-ttt\">reperfusion</span> ; transplantation d'organe ; <span class=\"kw-def\">cirrhose</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong><span class=\"kw-alerte\">Choc</span> <span class=\"kw-etio\">hémorragique</span></strong> — première cause de <span class=\"kw-def\">choc hypovolémique</span>. Étiologies par ordre de fréquence :</p>\n      <ul>\n        <li><strong>Saignement digestif</strong> — 1ʳᵉ cause de <span class=\"kw-alerte\">choc</span> <span class=\"kw-etio\">hémorragique</span>.</li>\n        <li><strong>Saignement traumatique</strong> — 2ᵉ cause : extériorisé (épistaxis, plaie du scalp, fracture ouverte, plaie vasculaire) ou interne (gros vaisseaux thoraciques, organes pleins abdominaux — rate, foie, reins ; fracture du bassin → hémorragie rétro-péritonéale).</li>\n        <li><strong>Autres</strong> — <span class=\"kw-alerte\">rupture</span> d'anévrysme aortique ; saignements gynécologiques (<span class=\"kw-ci\">grossesse</span> extra-utérine, hémorragie de la délivrance) ; hémoptysies massives ; hémorragie post-opératoire.</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>Piège.</strong> Devant un traumatisme crânien, rechercher une hémorragie extériorisée (face, scalp) : <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">lésions cérébrales ne causent pas à elles seules un choc hémorragique</span>.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 158 — <span class=\"kw-def\">Sepsis</span> et <span class=\"kw-def\">choc septique</span> · 226 — <span class=\"kw-def\">Thrombose veineuse profonde</span> - EP · 338 — <span class=\"kw-clinique\">Œdème</span> de Quincke - <span class=\"kw-alerte\">anaphylaxie</span> · 339 — <span class=\"kw-clinique\">Syndrome coronarien</span> aiguë</em></p>","frequence":1},{"id":"332-3","rang":"B","rubrique":"Physiopathologie","titre":"Connaître la physiopathologie des états de choc selon leur étiologie","contenu":"<p>Face à la baisse du débit cardiaque, l'organisme met en jeu immédiatement des <span class=\"kw-def\">mécanismes adaptatifs</span> pour préserver la perfusion des organes nobles.</p>\n      <figure class=\"choc-fig choc-casc\" role=\"img\" aria-label=\"Cascade physiopathologique de l'adaptation au choc : la baisse du débit cardiaque déclenche une réponse sympathique de compensation (augmentation du retour veineux, de la pression artérielle, de la performance myocardique et des résistances vasculaires systémiques) qui préserve la perfusion du cœur et du cerveau. La baisse du transport en oxygène est compensée par une augmentation de l'extraction périphérique tant que le seuil critique de transport n'est pas dépassé. Au-delà, bascule en métabolisme anaérobie avec production de lactates et acidose, aboutissant à la souffrance d'organe, au syndrome de défaillance multiviscérale puis au décès.\">\n        <div class=\"choc-casc__node\"><b>↓ Débit cardiaque (DC)</b><small>baisse du transport en O₂</small></div>\n        <div class=\"choc-casc__arrow\"></div>\n        <div class=\"choc-casc__comp\">\n          <h5>Réponse sympathique — compensation</h5>\n          <div class=\"choc-casc__grid\">\n            <span>↑ retour veineux</span>\n            <span>↑ pression artérielle</span>\n            <span>↑ performance myocardique</span>\n            <span>↑ RVS</span>\n          </div>\n        </div>\n        <div class=\"choc-casc__arrow\"></div>\n        <div class=\"choc-casc__node\">Perfusion préservée au <b>cœur</b> et au <b>cerveau</b><small>territoires musculo-cutané, splanchnique ± reins sacrifiés</small></div>\n        <div class=\"choc-casc__arrow\"></div>\n        <div class=\"choc-casc__node\">↓ TaO₂ → <b>↑ EO₂</b> (extraction compensatrice)<small>VO₂ maintenue tant que possible</small></div>\n        <div class=\"choc-casc__arrow\"></div>\n        <div class=\"choc-casc__seuil\">╳ SEUIL CRITIQUE de TaO₂ dépassé</div>\n        <div class=\"choc-casc__arrow\"></div>\n        <div class=\"choc-casc__node choc-casc__node--danger\"><b>Métabolisme <span class=\"kw-etio\">anaérobie</span></b> → ↑ <span class=\"kw-bio\">lactates</span> + H⁺ → acidose métabolique</div>\n        <div class=\"choc-casc__arrow\"></div>\n        <div class=\"choc-casc__node choc-casc__node--danger\"><b>Souffrance d'organe</b> → SDMV → décès</div>\n        <figcaption>Tant que l'extraction (EO₂) compense la baisse du transport (TaO₂), la VO₂ tient ; une fois le seuil critique franchi, bascule en <span class=\"kw-etio\">anaérobie</span> et souffrance d'organe.</figcaption>\n      </figure>\n      <p><strong>Niveau macrocirculatoire</strong> — la baisse du DC déclenche une <span class=\"kw-def\">stimulation sympathique</span> :</p>\n      <ul>\n        <li>↑ <strong>retour veineux</strong> — vasoconstriction veineuse, transfert interstitiel d'eau et de sel.</li>\n        <li>↑ <strong>pression artérielle</strong> — vasoconstriction artérielle.</li>\n        <li>↑ <strong>performance myocardique</strong> — effets chronotrope + (↑ FC) et inotrope +.</li>\n        <li>↑ <strong>RVS</strong> — redistribution des débits : perfusion sacrifiée sur <span class=\"kw-clinique\">les</span> territoires <span class=\"kw-clinique\">musculo-cutané</span>, <span class=\"kw-clinique\">splanchnique</span> ± reins ; perfusion maintenue au <span class=\"kw-clinique\">cœur</span> et au <span class=\"kw-clinique\">cerveau</span>.</li>\n      </ul>\n      <p><strong>Niveau régional et cellulaire</strong> — adaptation de la bioénergétique : la baisse du <span class=\"kw-def\">TaO₂</span> entraîne une ↑ de l'<span class=\"kw-def\">EO₂</span> (redistribution sympathique, recrutement capillaire médié par le <span class=\"kw-def\">NO</span>) afin de maintenir une consommation d'O₂ (VO₂) constante.</p>\n      <div class=\"callout callout-danger\">\n        <strong>Seuil critique.</strong> Une fois le <span class=\"kw-alerte\">TaO₂ critique</span> dépassé, passage en <span class=\"kw-alerte\">métabolisme anaérobie</span> : formation de <span class=\"kw-bio\">lactates</span> (↑ <span class=\"kw-bio\">lactatémie</span>) et de protons H⁺ (<span class=\"kw-bio\">acidose métabolique</span>). Ces deux paramètres sont corrélés à la sévérité de la souffrance tissulaire.\n      </div>\n      <p><strong><span class=\"kw-def\">Physiopathologie</span> selon l'étiologie :</strong></p>\n      <ul>\n        <li><strong><span class=\"kw-alerte\">Choc</span> quantitatif</strong> (hypovolémique, cardiogénique) — baisse du <span class=\"kw-def\">TaO₂</span> ; <span class=\"kw-clinique\">les</span> capacités d'extraction (EO₂) sont augmentées pour compenser, notamment dans les territoires sacrifiés.</li>\n        <li><strong><span class=\"kw-alerte\">Choc</span> distributif</strong> (septique, anaphylactique, <span class=\"kw-etio\">inflammatoire</span>) — baisse des capacités d'<span class=\"kw-def\">extraction de l'O₂</span> (troubles microcirculatoires, <span class=\"kw-clinique\">œdème</span> interstitiel par fuite capillaire) ; le TaO₂ est normal ou augmenté.</li>\n      </ul>\n      <p><strong>Réponse biphasique du <span class=\"kw-alerte\">choc</span> <span class=\"kw-etio\">hémorragique</span> :</strong></p>\n      <ul>\n        <li><strong>Phase 1</strong> — stimulation sympathique : maintien de la PA, <span class=\"kw-clinique\">tachycardie</span> compensatrice. Une PA normale chez un patient en <span class=\"kw-alerte\">hémorragie active</span> ne doit pas retarder la prise en charge, surtout chez le sujet jeune.</li>\n        <li><strong>Phase 2</strong> — inhibition centrale du sympathique (après perte de <span class=\"kw-chiffre\">30-50 %</span> de la <span class=\"kw-clinique\">masse</span> sanguine) : baisse des RVS → <span class=\"kw-alerte\">chute de la PA</span>, et <span class=\"kw-alerte\">bradycardie paradoxale</span> qui précède l'<span class=\"kw-alerte\">arrêt cardiaque</span>.</li>\n      </ul>\n      <figure class=\"choc-fig choc-frise\" role=\"img\" aria-label=\"Frise de la réponse biphasique du choc hémorragique. Phase 1, compensation sympathique : la pression artérielle est maintenue et il existe une tachycardie compensatrice ; une pression artérielle normale n'élimine pas une hémorragie active. Phase 2, décompensation après perte de 30 à 50 pour cent de la masse sanguine : inhibition centrale du sympathique, baisse des résistances vasculaires, chute de la pression artérielle et bradycardie paradoxale précédant l'arrêt cardiaque.\">\n        <div class=\"choc-frise__track\">\n          <div class=\"choc-frise__seg seg--1\">\n            <span class=\"ph\">Phase 1 — Compensation sympathique</span>\n            <span class=\"det\">PA maintenue · <span class=\"kw-clinique\">tachycardie</span> compensatrice. Une PA normale n'élimine pas une <span class=\"kw-alerte\">hémorragie active</span>, surtout chez le sujet jeune.</span>\n          </div>\n          <div class=\"choc-frise__seg seg--2\">\n            <span class=\"ph\">Phase 2 — <span class=\"kw-alerte\">Décompensation</span></span>\n            <span class=\"det\">Après perte de <span class=\"kw-chiffre\">30–50 %</span> de la <span class=\"kw-clinique\">masse</span> sanguine : ↓ RVS → chute de la PA + <span class=\"kw-clinique\">bradycardie</span> paradoxale → <span class=\"kw-alerte\">arrêt cardiaque</span>.</span>\n          </div>\n        </div>\n        <div class=\"choc-frise__axis\">▸ perte sanguine croissante ▸</div>\n        <figcaption>Le basculement phase 1 → phase 2 précède l'<span class=\"kw-alerte\">arrêt cardiaque</span>.</figcaption>\n      </figure>\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">Drapeau rouge</span>.</strong> Dans un <span class=\"kw-alerte\">choc</span> <span class=\"kw-etio\">hémorragique</span>, l'<span class=\"kw-alerte\">absence de tachycardie</span> est un signe d'alerte : <span class=\"kw-clinique\">évolution</span> gravissime vers la phase 2.\n      </div>","frequence":2},{"id":"332-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques d’un état de choc","contenu":"<p>Le <span class=\"kw-def\">diagnostic positif</span> d'un <span class=\"kw-alerte\">état de choc</span> repose sur l'association d'une <strong><span class=\"kw-clinique\">hypotension</span> artérielle</strong>, d'<strong>au moins une <span class=\"kw-alerte\">défaillance</span> d'organe</strong> et de <strong>dosages biologiques</strong>.</p>\n      <p><strong>1. <span class=\"kw-clinique\">Hypotension</span> artérielle</strong> — non induite par une cause <span class=\"kw-etio\">iatrogène</span> (sédation, anesthésie). Un seul critère suffit :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">PAS</span> <span class=\"kw-chiffre\">&lt; 90 mmHg</span>, ou chute de <span class=\"kw-chiffre\">&gt; 40 mmHg</span> par rapport à la valeur initiale, ou chute de <span class=\"kw-chiffre\">&gt; 30 %</span> chez l'hypertendu.</li>\n        <li><span class=\"kw-clinique\">PAM</span> <span class=\"kw-chiffre\">&lt; 60-65 mmHg</span>.</li>\n        <li><span class=\"kw-clinique\">PAD</span> <span class=\"kw-chiffre\">&lt; 40 mmHg</span>.</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique.</strong> Une <span class=\"kw-alerte\">PA normale n'élimine pas un choc débutant</span>. De manière opérationnelle, toute <span class=\"kw-clinique\">hypotension</span> doit être considérée comme un potentiel <span class=\"kw-alerte\">état de choc</span>.\n      </div>\n      <p><strong>2. Au moins une <span class=\"kw-alerte\">défaillance</span> d'organe</strong> — témoins des mécanismes de compensation précoces (maintien du DC = FC × VES) :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Tachycardie réflexe</span> <span class=\"kw-chiffre\">&gt; 120 bpm</span> — attention aux patients sous bradycardisants (β-bloquants).</li>\n        <li><span class=\"kw-clinique\">Polypnée</span> <span class=\"kw-chiffre\">&gt; 22 cycles/min</span> — compensation d'une acidose métabolique ou atteinte pulmonaire.</li>\n        <li><span class=\"kw-clinique\">Marbrures</span> — débutent aux genoux ; leur extension est corrélée à la gravité, leur régression est un signe d'amélioration.</li>\n        <li><span class=\"kw-clinique\">Extrémités froides et cyanosées</span>.</li>\n        <li><span class=\"kw-clinique\">Temps de recoloration cutanée</span> allongé <span class=\"kw-chiffre\">&gt; 3-5 s</span> (idéalement au genou ou à l'index).</li>\n        <li><span class=\"kw-clinique\">Confusion, agitation</span> — un <span class=\"kw-alerte\">coma</span> doit faire suspecter un autre mécanisme (<span class=\"kw-clinique\">méningoencéphalite</span>, hématome).</li>\n        <li><span class=\"kw-clinique\">Oligurie</span> <span class=\"kw-chiffre\">&lt; 0,5 mL/kg/h</span> ou <span class=\"kw-chiffre\">&lt; 500 mL/jour</span>.</li>\n      </ul>\n      <p><strong>3. Dosages indispensables</strong> au diagnostic <span class=\"kw-ttt\">biologique</span> :</p>\n      <ul>\n        <li><span class=\"kw-bio\">Lactatémie</span> — une <span class=\"kw-bio\">hyperlactatémie</span> artérielle ou veineuse <span class=\"kw-chiffre\">&gt; 2 mmol/L</span> est un argument fort, corrélé à la gravité.</li>\n        <li><span class=\"kw-bio\">Gaz du sang</span> — recherche d'une <span class=\"kw-bio\">acidose métabolique</span>, également corrélée à la gravité.</li>\n      </ul>\n      <div class=\"callout callout-info\">\n        <strong>Calcul de la PAM.</strong> Deux formules : PAM = PAD + (PP / 3), avec PP = PAS − PAD ; ou PAM = [PAS + (2 × PAD)] / 3.\n      </div>","frequence":1},{"id":"332-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les éléments d’anamnèse et cliniques pour le diagnostic étiologique selon l’anamnèse et la clinique","contenu":"<p>L'anamnèse et l'examen clinique orientent rapidement vers le mécanisme du <span class=\"kw-alerte\">choc</span>, avant même <span class=\"kw-clinique\">les</span> examens complémentaires.</p>\n      <figure class=\"choc-fig choc-tree\" role=\"img\" aria-label=\"Arbre d'orientation étiologique d'un état de choc au lit du patient. Si fièvre ou foyer infectieux : choc septique. Sinon, si signes cutanés brutaux (œdème cervico-facial, urticaire, bronchospasme) : choc anaphylactique. Sinon, si turgescence jugulaire avec crépitants ou OAP : choc cardiogénique gauche. Sinon, si turgescence jugulaire sans signe pulmonaire d'OAP : choc cardiogénique droit ou obstructif. Sinon, jugulaires plates avec pâleur et contexte hémorragique : choc hypovolémique ou hémorragique.\">\n        <div class=\"choc-tree__start\">État de <span class=\"kw-alerte\">choc</span> confirmé</div>\n        <div class=\"choc-tree__arrow\"></div>\n        <div class=\"choc-tree__step\">\n          <div class=\"choc-tree__q\"><span class=\"kw-clinique\">Fièvre</span> · foyer <span class=\"kw-etio\">infectieux</span> · immunodépression ?</div>\n          <div class=\"choc-tree__yes t-sep\"><b><span class=\"kw-alerte\">Choc</span> septique</b><small>distributif</small></div>\n        </div>\n        <div class=\"choc-tree__non\">sinon ↓</div>\n        <div class=\"choc-tree__step\">\n          <div class=\"choc-tree__q\">Signes cutanés brutaux : <span class=\"kw-clinique\">œdème</span> cervico-facial · <span class=\"kw-clinique\">urticaire</span> · bronchospasme ?</div>\n          <div class=\"choc-tree__yes t-ana\"><b><span class=\"kw-alerte\">Choc</span> anaphylactique</b><small>distributif · <span class=\"kw-ttt\">adrénaline</span> d'emblée</small></div>\n        </div>\n        <div class=\"choc-tree__non\">sinon ↓</div>\n        <div class=\"choc-tree__step\">\n          <div class=\"choc-tree__q\"><span class=\"kw-clinique\">Turgescence jugulaire</span> <b>+</b> <span class=\"kw-clinique\">crépitants</span> / <span class=\"kw-alerte\">OAP</span> ?</div>\n          <div class=\"choc-tree__yes t-cg\"><b>Cardiogénique « gauche »</b><small><span class=\"kw-clinique\">douleur thoracique</span> · souffle</small></div>\n        </div>\n        <div class=\"choc-tree__non\">sinon ↓</div>\n        <div class=\"choc-tree__step\">\n          <div class=\"choc-tree__q\"><span class=\"kw-clinique\">Turgescence jugulaire</span> <b>sans</b> signe pulmonaire d'<span class=\"kw-alerte\">OAP</span> ?</div>\n          <div class=\"choc-tree__yes t-obs\"><b>Cardiogénique « droit » / obstructif</b><small>EP · <span class=\"kw-alerte\">tamponnade</span> · PNO compressif</small></div>\n        </div>\n        <div class=\"choc-tree__non\">sinon ↓</div>\n        <div class=\"choc-tree__step\">\n          <div class=\"choc-tree__q\">Jugulaires plates + pâleur · hémorragie · contexte (anticoag, post-op, pertes) ?</div>\n          <div class=\"choc-tree__yes t-hem\"><b>Hypovolémique / <span class=\"kw-etio\">hémorragique</span></b><small>quantitatif</small></div>\n        </div>\n        <figcaption>La <span class=\"kw-clinique\">turgescence jugulaire</span> (pleine <span class=\"kw-bio\">vs</span> plate) est le pivot du raisonnement entre chocs distributifs, cardiogéniques/obstructifs et hypovolémiques.</figcaption>\n      </figure>\n      <table >\n        <thead><tr><th>Type de <span class=\"kw-alerte\">choc</span></th><th>Éléments d'orientation anamnestiques et cliniques</th></tr></thead>\n        <tbody>\n          <tr><th>Septique</th><td><span class=\"kw-clinique\">Fièvre</span> ; foyer <span class=\"kw-etio\">infectieux</span> patent ; <span class=\"kw-clinique\">immunodépression</span></td></tr>\n          <tr><th>Cardiogénique « gauche »</th><td><span class=\"kw-def\">Facteurs de risque</span> cardiovasculaires ; <span class=\"kw-clinique\">douleur thoracique</span> ; <span class=\"kw-clinique\">souffle cardiaque</span> ; <span class=\"kw-clinique\">turgescence jugulaire</span> ; <span class=\"kw-clinique\">crépitants</span> pulmonaires bilatéraux</td></tr>\n          <tr><th>Cardiogénique « droit » ou obstructif</th><td><span class=\"kw-clinique\">Turgescence jugulaire</span> sans signe pulmonaire d'<span class=\"kw-def\">OAP</span></td></tr>\n          <tr><th>Hypovolémique / <span class=\"kw-etio\">hémorragique</span></th><td>Hémorragie ; <span class=\"kw-clinique\">pâleur</span> ; prise d'<span class=\"kw-ttt\">anticoagulant</span> ; hématomes ; post-opératoire immédiat ; diarrhées abondantes ; coup de chaleur ; <span class=\"kw-clinique\">jugulaires plates</span> en décubitus</td></tr>\n          <tr><th>Anaphylactique</th><td>Signes cutanés brutaux : <span class=\"kw-clinique\">œdème cervico-facial / pharyngé</span> ; <span class=\"kw-clinique\">urticaire</span> (<span class=\"kw-clinique\">prurit</span>, <span class=\"kw-clinique\">érythème</span>) ; <span class=\"kw-clinique\">bronchospasme</span> ; trace de piqûre d'hyménoptère ; introduction récente d'un traitement ou repas avec allergène à risque dans <span class=\"kw-clinique\">les</span> heures précédentes</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 158 — <span class=\"kw-def\">Sepsis</span> et <span class=\"kw-def\">choc septique</span> · 338 — <span class=\"kw-clinique\">Œdème</span> de Quincke - <span class=\"kw-alerte\">anaphylaxie</span> · 339 — <span class=\"kw-clinique\">Syndrome coronarien</span> aiguë</em></p>","frequence":3},{"id":"332-6","rang":"B","rubrique":"Examens complémentaires","titre":"Savoir caractériser le type d’état de choc","contenu":"<p>Caractériser le type d'<span class=\"kw-alerte\">état de choc</span> repose sur l'évaluation des <span class=\"kw-def\">déterminants de l'oxygénation tissulaire</span> et sur le <span class=\"kw-def\">profil de pression artérielle</span>.</p>\n      <p><strong>Déterminants de l'oxygénation tissulaire :</strong></p>\n      <ul>\n        <li><span class=\"kw-def\">TaO₂</span> (transport artériel en O₂) = DC × CaO₂ ; <span class=\"kw-def\">CaO₂</span> = Hb × 1,34 × SaO₂ ; DC = FC × VES.</li>\n        <li><span class=\"kw-def\">EO₂</span> (extraction périphérique) = (SaO₂ − SvO₂) / SaO₂ ≈ <span class=\"kw-chiffre\">25-30 %</span>.</li>\n        <li>En pratique, on mesure la <span class=\"kw-bio\">SvcO₂</span> sur une voie veineuse centrale cave supérieure : à SaO₂ normale, une <span class=\"kw-bio\">SvcO₂ &lt; 70 %</span> fait rechercher une baisse du TaO₂.</li>\n      </ul>\n      <table >\n        <thead><tr><th>Type</th><th>Mécanisme</th><th>Profil de pression artérielle</th></tr></thead>\n        <tbody>\n          <tr>\n            <th><span class=\"kw-alerte\">Choc</span> quantitatif<br>(hypovolémique, cardiogénique)</th>\n            <td>↓ TaO₂ par baisse du DC ; EO₂ augmentée en compensation</td>\n            <td><strong>↓ PP</strong> (pression pulsée)<br><strong>↑ PAD</strong> — compensation du ↓ VES par ↑ RVS</td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-alerte\">Choc</span> distributif<br>(septique, anaphylactique, <span class=\"kw-etio\">inflammatoire</span>)</th>\n            <td>↓ EO₂ (troubles microcirculatoires, <span class=\"kw-clinique\">œdème</span> interstitiel) ; TaO₂ normal ou ↑</td>\n            <td><strong>↓ PAD</strong> — vasoplégie → ↓ RVS<br><strong>↑ PP</strong> — ↑ VES par compensation cardiaque</td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Profil hémodynamique</strong> des quatre types de <span class=\"kw-alerte\">choc</span> :</p>\n      <table >\n        <thead><tr><th>Type de choc</th><th>PVC (précharge)</th><th>Débit cardiaque</th><th>RVS</th><th>SvO₂</th></tr></thead>\n        <tbody>\n          <tr><th>Hypovolémique</th><td>↓</td><td>↓</td><td>↑</td><td>↓</td></tr>\n          <tr><th>Cardiogénique</th><td>↑</td><td>↓</td><td>↑</td><td>↓</td></tr>\n          <tr><th>Distributif (septique / anaphylactique)</th><td>↓ / N</td><td>↑ (ou N)</td><td>↓</td><td>↑ / N</td></tr>\n          <tr><th>Obstructif</th><td>↑</td><td>↓</td><td>↑</td><td>↓</td></tr>\n        </tbody>\n      </table>\n      <p>Rappel : la <span class=\"kw-def\">PAD</span> reflète <span class=\"kw-clinique\">les</span> résistances artérielles systémiques ; la <span class=\"kw-def\">PP</span> (PAS − PAD) est corrélée au volume d'éjection systolique.</p>\n      <div class=\"callout callout-warn\">\n        <strong>Nuance — valvulopathie aortique.</strong> En cas d'<span class=\"kw-clinique\">insuffisance aortique</span> sévère, la PP est <strong>élargie</strong> (régurgitation → ↑ VTD → ↑ VES). En cas de <span class=\"kw-clinique\">rétrécissement aortique</span> sévère, la PP est <strong>pincée</strong> (↑ post-charge → ↓ VES).\n      </div>","frequence":3,"liens":[{"href":"https://radiopaedia.org/articles/gastrointestinal-bleeding","label":"Radiopaedia : Gastrointestinal bleeding"},{"href":"https://radiopaedia.org/articles/postpartum-haemorrhage","label":"Radiopaedia : Postpartum haemorrhage"}]},{"id":"332-7","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître la stratégie d’exploration devant un choc hémorragique","contenu":"<p>L'exploration d'un <span class=\"kw-alerte\">choc</span> <span class=\"kw-etio\">hémorragique</span> associe un <strong>bilan <span class=\"kw-ttt\">biologique</span> de gravité</strong> et un <strong>bilan étiologique</strong> guidé par le contexte.</p>\n      <p><strong>Bilan <span class=\"kw-ttt\">biologique</span> spécifique</strong> (en plus des examens de tout <span class=\"kw-alerte\">état de choc</span>) :</p>\n      <ul>\n        <li><span class=\"kw-bio\">Gaz du sang artériel</span> avec <span class=\"kw-bio\">lactate</span> et <span class=\"kw-bio\">calcémie ionisée</span>.</li>\n        <li><span class=\"kw-bio\">NFS-plaquettes</span> — en attendant <span class=\"kw-clinique\">les</span> résultats, l'Hb est surveillée au lit du patient (<span class=\"kw-bio\">HemoCue</span>).</li>\n        <li><span class=\"kw-bio\">Groupage sanguin</span> + <span class=\"kw-bio\">RAI</span> — indispensables avant toute transfusion.</li>\n        <li><span class=\"kw-bio\">Bilan de coagulation</span> (<span class=\"kw-bio\">TP</span>, <span class=\"kw-bio\">TCA</span>, <span class=\"kw-bio\">fibrinogène</span>) — apprécie la <span class=\"kw-alerte\">coagulopathie de consommation</span>, guide l'administration des produits sanguins labiles, dépiste une <span class=\"kw-alerte\">CIVD</span> ou une anomalie de l'hémostase (hémophilie, <span class=\"kw-ttt\">anticoagulant</span>).</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique.</strong> Le <span class=\"kw-alerte\">taux d'Hb peut être faussement normal</span> à la phase initiale du <span class=\"kw-alerte\">choc</span> <span class=\"kw-etio\">hémorragique</span>, avant le remplissage vasculaire (il s'agit d'une concentration).\n      </div>\n      <p><strong>Bilan étiologique selon le contexte :</strong></p>\n      <table >\n        <thead><tr><th>Contexte</th><th>Stratégie d'exploration</th></tr></thead>\n        <tbody>\n          <tr><th>Traumatique</th><td><strong>Malade stable :</strong> <span class=\"kw-imagerie\">TDM corps entier injecté</span><br><strong>Malade instable :</strong> <span class=\"kw-imagerie\">RXT</span> + <span class=\"kw-imagerie\">radiographie du bassin</span> + <span class=\"kw-imagerie\">FAST écho</span> → <span class=\"kw-ttt\">chirurgie</span> de damage control</td></tr>\n          <tr><th>Hémorragie extériorisée</th><td><strong>Digestive</strong> (<span class=\"kw-clinique\">méléna</span>, <span class=\"kw-clinique\">rectorragies</span>, <span class=\"kw-clinique\">hématémèse</span>) : <span class=\"kw-imagerie\">EOGD</span><br><strong>Délivrance :</strong> révision utérine ; examen sous valve ; utérotoniques ; ± artériographie-embolisation</td></tr>\n          <tr><th>Hémorragie non extériorisée</th><td>Interrogatoire (retard de règles → GEU ; ATCD d'anévrysme ; <span class=\"kw-ttt\">anticoagulants</span> → hématome profond ; contexte chirurgical) ; <span class=\"kw-imagerie\">TDM-TAP injecté</span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 329 — Transfusion sanguine · 334 — PEC immédiate trauma : polytraumatisme, brûlure, <span class=\"kw-clinique\">hypothermie</span>…</em></p>","frequence":4},{"id":"332-8","rang":"A","rubrique":"Prise en charge","titre":"Connaître les éléments de prise en charge immédiate d’un état de choc","contenu":"<p>L'<span class=\"kw-alerte\">état de choc</span> est une <strong><span class=\"kw-alerte\">urgence</span> thérapeutique</strong> nécessitant le plus souvent une admission en <span class=\"kw-clinique\">réanimation</span>. La prise en charge est simultanée : symptomatique (hémodynamique, respiratoire) et étiologique (arrêt du mécanisme causal).</p>\n      <p><strong>Monitorage :</strong></p>\n      <ul>\n        <li>En <span class=\"kw-alerte\">urgence</span> prioritaire — <span class=\"kw-clinique\">SpO₂</span>, <span class=\"kw-clinique\">scope ECG</span>, <span class=\"kw-clinique\">PA automatique non invasive</span>.</li>\n        <li>Dans un 2ᵉ temps — <span class=\"kw-clinique\">PA invasive</span> sur cathéter artériel (nécessaire si catécholamines) ; <span class=\"kw-imagerie\">ETT</span> répétée, examen de référence pour l'évaluation hémodynamique ; <span class=\"kw-bio\">GDS</span> et <span class=\"kw-bio\">lactatémie</span> répétés.</li>\n      </ul>\n      <p><strong>Expansion volémique</strong> — fondamentale, <span class=\"kw-ci\">sauf choc obstructif ou cardiogénique sans composante hypovolémique</span> (risque d'<span class=\"kw-def\">OAP</span>) :</p>\n      <ul>\n        <li>Solutés <span class=\"kw-ttt\">cristalloïdes</span> — Ringer <span class=\"kw-bio\">Lactate</span> (balancé) ou NaCl <span class=\"kw-chiffre\">0,9 %</span>.</li>\n        <li>Position déclive (Trendelenburg) en attendant ; pose d'une VVP de bon calibre.</li>\n        <li>Perfuser jusqu'à <span class=\"kw-chiffre\">30 mL/kg</span> (<span class=\"kw-chiffre\">20 mL/kg</span> chez l'enfant) jusqu'à PAM <span class=\"kw-chiffre\">≥ 65 mmHg</span>, puis adapter après évaluation de la précharge.</li>\n      </ul>\n      <p><strong>Catécholamines</strong> — indiquées si PAM &lt;<span class=\"kw-chiffre\"> 65 mmHg</span> malgré le remplissage, si PAD &lt;<span class=\"kw-chiffre\"> 40 mmHg</span> (vasoplégie intense), ou d'emblée dans le <span class=\"kw-def\">choc anaphylactique</span> :</p>\n      <table >\n        <thead><tr><th>Catécholamine</th><th>Propriétés</th><th>Indications</th></tr></thead>\n        <tbody>\n          <tr><th>Noradrénaline</th><td>Vasoconstricteur <span class=\"kw-def\">α1</span> prédominant (β1 moindre)</td><td><strong>1ʳᵉ intention</strong> dans la majorité des chocs : <span class=\"kw-def\">choc septique</span>, <span class=\"kw-def\">choc cardiogénique</span> avec <span class=\"kw-clinique\">hypotension</span></td></tr>\n          <tr><th>Adrénaline</th><td>α et <span class=\"kw-def\">β1</span> (inotrope +)</td><td><span class=\"kw-alerte\">Choc</span> réfractaire (2ᵉ intention) ; <span class=\"kw-def\">choc anaphylactique</span> ; <span class=\"kw-alerte\">arrêt cardiaque</span></td></tr>\n          <tr><th>Dobutamine</th><td>Inodilatateur <span class=\"kw-def\">β1</span> puissant</td><td><span class=\"kw-def\">Choc cardiogénique</span> — index cardiaque &lt;<span class=\"kw-chiffre\"> 2,5 L</span>/min/m²</td></tr>\n        </tbody>\n      </table>\n      <p>Administration <strong>en continu à la seringue électrique</strong>, sur <span class=\"kw-clinique\">VVC</span> (VVP possible en attendant la pose). Seule l'<span class=\"kw-ttt\">adrénaline</span> peut s'utiliser en bolus.</p>\n      <div class=\"callout callout-info\">\n        <strong>Objectifs (en &lt;<span class=\"kw-chiffre\"> 3 h</span>, idéalement &lt;<span class=\"kw-chiffre\"> 1 h</span>).</strong> PAM &gt;<span class=\"kw-chiffre\"> 65 mmHg</span> ; correction des marbrures ; baisse de l'acidose et de l'hyperlactatémie ; reprise de la diurèse.\n      </div>\n      <p><strong>Mesures associées selon le contexte :</strong></p>\n      <ul>\n        <li><strong><span class=\"kw-ttt\">Ventilation mécanique</span></strong> si l'<span class=\"kw-ttt\">oxygénothérapie</span> ne corr<span class=\"kw-chiffre\">ige</span> pas l'hypoxémie ou en cas d'agitation — attention au risque d'aggravation hémodynamique (vasoplégie des sédatifs, ↓ retour veineux).</li>\n        <li><strong><span class=\"kw-bio\">Bicarbonates</span></strong> si pertes digestives/rénales de HCO₃⁻ ou hyperkaliémie menaçante ; <strong>épuration extra-rénale</strong> si acidose sévère ou réfractaire.</li>\n        <li><strong><span class=\"kw-ttt\">Hydrocortisone</span></strong> (opothérapie substitutive) si <span class=\"kw-alerte\">choc</span> grave nécessitant des doses élevées ou croissantes d'amines.</li>\n      </ul>\n      <p><strong><span class=\"kw-ttt\">Oxygénothérapie</span></strong> — ne corr<span class=\"kw-chiffre\">ige</span> pas le <span class=\"kw-alerte\">choc</span> mais prévient l'hypoxémie associée : masque à haute concentration (<span class=\"kw-chiffre\">≥ 15 L</span>/min). <strong>Arrêt du mécanisme causal</strong> : éviction de l'allergène, exsufflation d'un <span class=\"kw-imagerie\">pneumothorax</span> compressif, 1ʳᵉ dose d'antibiotique &lt;<span class=\"kw-chiffre\"> 1 h</span> si <span class=\"kw-def\">sepsis</span>, contrôle d'une hémorragie.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 359 — <span class=\"kw-alerte\">Détresse</span> et <span class=\"kw-ci\">insuffisance respiratoire</span> aiguë</em></p>","frequence":4},{"id":"332-9","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de prise en charge du choc hémorragique","contenu":"<p>La prise en charge du <span class=\"kw-alerte\">choc</span> <span class=\"kw-etio\">hémorragique</span> vise à <strong>contrôler le saignement</strong>, <strong>restaurer la volémie et l'hémostase</strong> et <strong>lutter contre la triade létale</strong>.</p>\n      <div class=\"callout callout-info\">\n        <strong>Objectifs tensionnels — <span class=\"kw-clinique\">hypotension</span> permissive.</strong> Avant le contrôle de l'hémorragie, un niveau de PA bas est toléré : <span class=\"kw-chiffre\">PAS 80-90 mmHg</span> ou <span class=\"kw-chiffre\">PAM 60-65 mmHg</span>. Exception : <span class=\"kw-alerte\">traumatisme crânien grave (Glasgow ≤ 8) ou médullaire</span> → maintenir une <span class=\"kw-chiffre\">PAM ≥ 80 mmHg</span> pour préserver la perfusion cérébrale ou médullaire.\n      </div>\n      <p><strong>Remplissage et catécholamines :</strong></p>\n      <ul>\n        <li>2 VVP de gros calibre (VVC fémorale ou cathéter intra-osseux si VVP impossible).</li>\n        <li><span class=\"kw-ttt\">Cristalloïdes</span> limités à <span class=\"kw-chiffre\">1 L</span> — éviter l'hémodilution, la priorité étant de ramener du sang.</li>\n        <li><span class=\"kw-ci\">Pas de solutés hypotoniques</span> (sérum glucosé) : pouvoir d'expansion faible, à bannir chez le traumatisé crânien ou médullaire (majore l'<span class=\"kw-clinique\">œdème</span>).</li>\n        <li><span class=\"kw-ttt\">Noradrénaline</span> si PAS <span class=\"kw-chiffre\">≤ 80 mmHg</span> ou PAM &lt;<span class=\"kw-chiffre\"> 65 mmHg</span> malgré un remplissage de <span class=\"kw-chiffre\">1000-1500 mL</span>.</li>\n      </ul>\n      <p><strong>Transfusion de produits sanguins labiles :</strong></p>\n      <table >\n        <thead><tr><th>Produit</th><th>Modalités</th><th>Objectif</th></tr></thead>\n        <tbody>\n          <tr><th>CGR</th><td>Pas de seuil fixe ; dépend de la tolérance et de la cinétique de déglobulisation</td><td>Hb <span class=\"kw-chiffre\">7-9 g/dL</span> ; hémorragie digestive du cirrhotique 7-8 ; coronaropathie sévère 9-10 ; neurotraumatisme <span class=\"kw-chiffre\">&gt; 10 g/dL</span></td></tr>\n          <tr><th>PFC</th><td>Administré précocement avec <span class=\"kw-clinique\">les</span> CGR, ratio PFC/CGR de <span class=\"kw-chiffre\">1/2 à 1/1</span></td><td><span class=\"kw-bio\">TP</span> <span class=\"kw-chiffre\">&gt; 40 %</span> ; neurotraumatisme <span class=\"kw-bio\">TP</span> &gt;<span class=\"kw-chiffre\"> 50-60 %</span></td></tr>\n          <tr><th><span class=\"kw-bio\">Fibrinogène</span></th><td>En parallèle des CGR et PFC (quasi absent des PFC) ; dose initiale ≈<span class=\"kw-chiffre\"> 3 g</span></td><td>Taux <span class=\"kw-chiffre\">&gt; 1,5 g/L</span></td></tr>\n          <tr><th><span class=\"kw-bio\">Plaquettes</span> (CP)</th><td>Seulement une fois la numération plaquettaire connue ; ratio ≈ 1/4</td><td><span class=\"kw-bio\">Plaquettes</span> <span class=\"kw-chiffre\">&gt; 50 G/L</span> ; trauma crânien ou saignement persistant <span class=\"kw-chiffre\">&gt; 100 G/L</span></td></tr>\n        </tbody>\n      </table>\n      <p>En <strong><span class=\"kw-alerte\">urgence</span> vitale immédiate</strong>, groupe non connu : <span class=\"kw-bio\">CGR O−</span> pour <span class=\"kw-clinique\">les</span> femmes avant la ménopause, <span class=\"kw-bio\">CGR O+</span> pour les autres patients ; la <span class=\"kw-bio\">RAI</span> reste indispensable même en urgence.</p>\n      <div class=\"callout callout-danger\">\n        <strong>Triade létale auto-aggravatrice.</strong> <span class=\"kw-alerte\">Hypothermie</span> (&lt;<span class=\"kw-chiffre\"> 35 °C</span>) + <span class=\"kw-alerte\">acidose</span> (<span class=\"kw-bio\">pH</span> &lt; 7,2) + <span class=\"kw-alerte\">coagulopathie</span> (<span class=\"kw-bio\">INR</span> &gt; 1,5). Elle traduit l'impossibilité d'arrêter le saignement et cause le décès du patient.\n      </div>\n      <figure class=\"choc-fig choc-triade\" role=\"img\" aria-label=\"Cercle vicieux de la triade létale du choc hémorragique : hypothermie inférieure à 35 degrés, acidose avec pH inférieur à 7,2 et coagulopathie avec INR supérieur à 1,5 s'auto-aggravent en boucle autour d'un saignement incontrôlable. Chaque sommet aggrave le suivant, entretenant l'hémorragie.\">\n        <svg viewBox=\"0 0 420 300\" xmlns=\"http://www.w3.org/2000/svg\">\n          <defs>\n            <marker id=\"ar332\" viewBox=\"0 0 10 10\" refX=\"8\" refY=\"5\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\">\n              <path d=\"M0 0 L10 5 L0 10 z\" fill=\"var(--choc-svg-red)\"/>\n            </marker>\n          </defs>\n          <circle cx=\"210\" cy=\"160\" r=\"60\" fill=\"var(--choc-svg-red)\" fill-opacity=\"0.06\" stroke=\"var(--accent-dash)\" stroke-width=\"1.5\" stroke-dasharray=\"4 4\"/>\n          <text x=\"210\" y=\"153\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"700\" fill=\"var(--choc-svg-red)\">Saignement</text>\n          <text x=\"210\" y=\"171\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"700\" fill=\"var(--choc-svg-red)\">incontrôlable</text>\n          <path d=\"M252 80 Q322 130 318 220\" fill=\"none\" stroke=\"var(--choc-svg-red)\" stroke-width=\"2.5\" marker-end=\"url(#ar332)\"/>\n          <path d=\"M262 268 Q210 288 158 268\" fill=\"none\" stroke=\"var(--choc-svg-red)\" stroke-width=\"2.5\" marker-end=\"url(#ar332)\"/>\n          <path d=\"M102 220 Q98 130 168 80\" fill=\"none\" stroke=\"var(--choc-svg-red)\" stroke-width=\"2.5\" marker-end=\"url(#ar332)\"/>\n          <g>\n            <rect x=\"132\" y=\"28\" width=\"156\" height=\"48\" rx=\"11\" fill=\"var(--choc-svg-red)\" fill-opacity=\"0.13\" stroke=\"var(--choc-svg-red)\" stroke-width=\"1.5\"/>\n            <text x=\"210\" y=\"50\" text-anchor=\"middle\" font-size=\"13.5\" font-weight=\"700\" fill=\"var(--ink)\"><span class=\"kw-clinique\">Hypothermie</span></text>\n            <text x=\"210\" y=\"67\" text-anchor=\"middle\" font-size=\"11\" fill=\"var(--ink-muted)\">&lt;<span class=\"kw-chiffre\"> 35 °C</span></text>\n          </g>\n          <g>\n            <rect x=\"14\" y=\"232\" width=\"150\" height=\"48\" rx=\"11\" fill=\"var(--choc-svg-red)\" fill-opacity=\"0.13\" stroke=\"var(--choc-svg-red)\" stroke-width=\"1.5\"/>\n            <text x=\"89\" y=\"254\" text-anchor=\"middle\" font-size=\"13.5\" font-weight=\"700\" fill=\"var(--ink)\">Acidose</text>\n            <text x=\"89\" y=\"271\" text-anchor=\"middle\" font-size=\"11\" fill=\"var(--ink-muted)\">pH &lt; 7,2</text>\n          </g>\n          <g>\n            <rect x=\"256\" y=\"232\" width=\"150\" height=\"48\" rx=\"11\" fill=\"var(--choc-svg-red)\" fill-opacity=\"0.13\" stroke=\"var(--choc-svg-red)\" stroke-width=\"1.5\"/>\n            <text x=\"331\" y=\"254\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"700\" fill=\"var(--ink)\">Coagulopathie</text>\n            <text x=\"331\" y=\"271\" text-anchor=\"middle\" font-size=\"11\" fill=\"var(--ink-muted)\"><span class=\"kw-bio\">INR</span> &gt; 1,5</text>\n          </g>\n        </svg>\n        <figcaption>Triade létale auto-aggravatrice : chaque sommet entretient <span class=\"kw-clinique\">les</span> deux autres autour du saignement. La rompre = réchauffer, corriger l'acidose et restaurer l'hémostase.</figcaption>\n      </figure>\n      <p><strong>Contrôle du saignement</strong> — priorité absolue : déterminer et contrôler l'origine du saignement par <span class=\"kw-ttt\">garrot</span> (noter l'heure de pose), <span class=\"kw-ttt\">chirurgie</span>, <span class=\"kw-ttt\">endoscopie</span> ou <span class=\"kw-ttt\">radio-embolisation</span> ; <span class=\"kw-ttt\">acide tranexamique</span> (anti-fibrinolytique) <span class=\"kw-chiffre\">1 g</span> dès que possible, puis <span class=\"kw-chiffre\">1 g sur 8 h</span>.</p>\n      <p><strong>Mesures associées</strong> : lutte contre l'<span class=\"kw-alerte\">hypothermie</span> (couverture, perfusions réchauffées) ; correction de l'<span class=\"kw-bio\">hypocalcémie</span> par <span class=\"kw-ttt\">chlorure de calcium</span> IV — le citrate des poches de transfusion chélate le calcium — objectif <span class=\"kw-chiffre\">calcium ionisé &gt; 0,9 mmol/L</span>.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 329 — Transfusion sanguine · 334 — PEC immédiate trauma : polytraumatisme, brûlure, <span class=\"kw-clinique\">hypothermie</span>…</em></p>","frequence":4},{"id":"332-10","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de prise en charge du choc septique","contenu":"<p>Le <span class=\"kw-def\">choc septique</span> est un <span class=\"kw-alerte\">choc</span> <span class=\"kw-def\">distributif</span>. Sa prise en charge associe un traitement <strong>hémodynamique</strong> et un traitement <strong>spécifique</strong> de l'infection.</p>\n      <ul>\n        <li><strong>Traitement hémodynamique</strong> — <span class=\"kw-ttt\">remplissage vasculaire</span> + <span class=\"kw-ttt\">noradrénaline</span> ± <span class=\"kw-ttt\">dobutamine</span> en cas de dysfonction cardiaque associée.</li>\n        <li><strong>Traitement spécifique</strong> — <span class=\"kw-ttt\">antibiothérapie</span> (1ʳᵉ dose &lt;<span class=\"kw-chiffre\"> 1 h</span>) ± <span class=\"kw-clinique\">drainage ou chirurgie</span> selon le site <span class=\"kw-etio\">infectieux</span>.</li>\n      </ul>\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> La <span class=\"kw-ttt\">noradrénaline</span> corr<span class=\"kw-chiffre\">ige</span> la <span class=\"kw-alerte\">vasoplégie</span> du <span class=\"kw-alerte\">choc</span> distributif. L'<span class=\"kw-ttt\">antibiothérapie</span> précoce relève de l'arrêt du mécanisme causal — chaque heure de retard aggrave le <span class=\"kw-def\">pronostic</span>.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 158 — <span class=\"kw-def\">Sepsis</span> et <span class=\"kw-def\">choc septique</span></em></p>","frequence":4},{"id":"332-11","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de prise en charge du choc cardiogénique","contenu":"<p>Le <span class=\"kw-def\">choc cardiogénique</span> est le plus souvent secondaire à un <span class=\"kw-clinique\">syndrome coronarien aigu</span>.</p>\n      <ul>\n        <li><strong>Traitement hémodynamique</strong> — <span class=\"kw-ci\">pas de remplissage</span> (sauf <span class=\"kw-clinique\">infarctus</span> du ventricule droit) ; <span class=\"kw-ttt\">dobutamine</span> ± <span class=\"kw-ttt\">noradrénaline</span> si <span class=\"kw-clinique\">hypotension</span> persistante et profonde ; ± assistance circulatoire veino-artérielle (ECMO).</li>\n        <li><strong>Traitement spécifique</strong> — <span class=\"kw-clinique\">revascularisation coronaire</span>.</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>Piège.</strong> Le remplissage est <span class=\"kw-ci\">contre-indiqué</span> dans le <span class=\"kw-def\">choc cardiogénique</span> sans composante hypovolémique (risque d'<span class=\"kw-alerte\">OAP</span>). Seule exception : l'<span class=\"kw-clinique\">infarctus</span> du ventricule droit.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 234 — <span class=\"kw-def\">Insuffisance cardiaque</span> · 339 — <span class=\"kw-clinique\">Syndrome coronarien</span> aiguë</em></p>","frequence":1},{"id":"332-12","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de prise en charge du choc obstructif","contenu":"<p>Le <span class=\"kw-alerte\">choc</span> obstructif résulte d'un <span class=\"kw-def\">obstacle mécanique</span> au remplissage ou à l'éjection cardiaque : <span class=\"kw-def\">embolie pulmonaire</span>, <span class=\"kw-alerte\">tamponnade</span>, <span class=\"kw-imagerie\">pneumothorax</span> compressif.</p>\n      <ul>\n        <li><strong>Traitement hémodynamique</strong> — <span class=\"kw-ttt\">remplissage limité à 500 mL</span> de cristalloïdes ; <span class=\"kw-ttt\">noradrénaline</span>.</li>\n        <li><strong>Traitement spécifique = lever l'obstacle</strong> — <span class=\"kw-ttt\">thrombolyse</span> si <span class=\"kw-def\">embolie pulmonaire</span> ; <span class=\"kw-clinique\">ponction / drainage ou évacuation chirurgicale</span> si <span class=\"kw-alerte\">tamponnade</span> ; exsufflation (2ᵉ espace intercostal) si <span class=\"kw-imagerie\">pneumothorax</span> compressif.</li>\n      </ul>\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Le traitement décisif est étiologique : lever l'obstacle. Le support hémodynamique n'est qu'un pont en attendant — le remplissage y est volontairement limité.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 226 — <span class=\"kw-def\">Thrombose veineuse profonde</span> - EP · 235 — Péricardite aiguë</em></p>","frequence":1},{"id":"332-13","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de prise en charge du choc anaphylactique (dont la posologie de l’adrénaline par voie intramusculaire)","contenu":"<p>Le <span class=\"kw-def\">choc anaphylactique</span> est un <span class=\"kw-alerte\">choc</span> <span class=\"kw-def\">distributif</span> par vasoplégie et fuite capillaire massive, d'installation brutale.</p>\n      <ul>\n        <li><strong>Traitement hémodynamique</strong> — <span class=\"kw-ttt\">adrénaline</span> d'emblée, en <span class=\"kw-alerte\">urgence</span> ; <span class=\"kw-ttt\">remplissage vasculaire</span>.</li>\n        <li><strong>Traitement spécifique</strong> — <span class=\"kw-ttt\">adrénaline</span> ; <span class=\"kw-clinique\">éviction de l'allergène</span>.</li>\n      </ul>\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">Urgence</span>.</strong> Dans le <span class=\"kw-def\">choc anaphylactique</span>, l'<span class=\"kw-alerte\">adrénaline est administrée d'emblée</span>, concomitamment au remplissage — sans attendre l'échec du remplissage, contrairement aux autres types de <span class=\"kw-alerte\">choc</span>.\n      </div>\n      <p><strong>Posologie de l'<span class=\"kw-ttt\">adrénaline</span> par voie intramusculaire</strong> — traitement de <strong>1ʳᵉ intention</strong>, à la <strong>face latéro-externe du 1/3 moyen de la cuisse</strong> ; dose = <span class=\"kw-chiffre\">0,01 mg/kg</span>, plafonnée à <span class=\"kw-chiffre\">0,5 mg</span> par injection, <strong>à répéter toutes <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">5 à 15 min</span></strong> si pas d'amélioration :</p>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Terrain</span></th><th>Dose IM</th></tr></thead>\n        <tbody>\n          <tr><td>Adulte / enfant &gt;<span class=\"kw-chiffre\"> 12 ans</span> ou &gt;<span class=\"kw-chiffre\"> 30 kg</span></td><td><span class=\"kw-chiffre\">0,3 à 0,5 mg</span> (300–<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>500</span> µg</span>)</td></tr>\n          <tr><td>Enfant <span class=\"kw-chiffre\">15–30 kg</span></td><td><span class=\"kw-chiffre\">0,15 mg</span> (<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>150</span> µg</span>)</td></tr>\n          <tr><td>Enfant &lt;<span class=\"kw-chiffre\"> 15 kg</span></td><td>≈ <span class=\"kw-chiffre\">0,1 mg / 10 kg</span> (pas d'AMM, appréciation médicale)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong><span class=\"kw-alerte\">Choc</span> réfractaire.</strong> Si persistance malgré des bolus IM répétés (ou patient sous <span class=\"kw-ttt\">bêtabloquant</span>), l'<span class=\"kw-ttt\">adrénaline</span> est titrée par voie <strong>IV</strong> (bolus de <span class=\"kw-chiffre\">0,001 mg/kg</span>) puis poursuivie à la <span class=\"kw-clinique\">seringue électrique en réanimation</span> ; le <span class=\"kw-ttt\">glucagon</span> est l'antidote en cas de blocage bêta-adrénergique.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 338 — <span class=\"kw-clinique\">Œdème</span> de Quincke - <span class=\"kw-alerte\">anaphylaxie</span></em></p>","frequence":2}],"astuces":[],"strategie":{"urgence":"<p><strong>Degré :</strong> <span class=\"kw-alerte\">urgence vitale</span> — <span class=\"kw-alerte\">urgence</span> thérapeutique nécessitant le plus souvent une admission en <span class=\"kw-alerte\">réanimation</span><br><strong>Fenêtre :</strong> objectifs hémodynamiques obtenus en <span class=\"kw-chiffre\">&lt; 3 h</span>, idéalement <span class=\"kw-chiffre\">&lt; 1 h</span><br><strong>1er geste :</strong> <span class=\"kw-ttt\">monitorage</span> prioritaire (<span class=\"kw-bio\">SpO2</span>, scope <span class=\"kw-bio\">ECG</span>, PA non invasive) ; <span class=\"kw-ttt\">position déclive (Trendelenburg)</span> ; <span class=\"kw-ttt\">2 VVP de bon calibre</span> ; <span class=\"kw-ttt\">remplissage vasculaire</span><br><strong>Causes à traiter sans délai :</strong> <span class=\"kw-ttt\">adrénaline IM</span> si <span class=\"kw-etio\">choc anaphylactique</span> ; <span class=\"kw-ttt\">antibiotique &lt; 1 h</span> si <span class=\"kw-etio\">choc septique</span> ; arrêt du saignement si <span class=\"kw-etio\">choc hémorragique</span></p>","redflags":"<ul><li><strong><span class=\"kw-clinique\">Hypotension</span></strong> : <span class=\"kw-clinique\">PAS &lt; 90 mmHg</span> ou chute <span class=\"kw-chiffre\">&gt; 40 mmHg</span> (ou <span class=\"kw-chiffre\">&gt; 30 %</span> chez l'hypertendu) ; <span class=\"kw-clinique\">PAM &lt; 60-65 mmHg</span> ; <span class=\"kw-clinique\">PAD &lt; 40 mmHg</span> — une PA normale n'élimine pas un <span class=\"kw-alerte\">choc</span> débutant</li><li><span class=\"kw-clinique\">Tachycardie réflexe &gt; 120 bpm</span> (masquée par <span class=\"kw-clinique\">les</span> bradycardisants : β-bloquants)</li><li><span class=\"kw-clinique\">Marbrures</span> (extension corrélée à la gravité), extrémités froides cyanosées, <span class=\"kw-clinique\">TRC &gt; 3-5 s</span></li><li><span class=\"kw-clinique\">Polypnée &gt; 22 cycles/min</span></li><li><span class=\"kw-clinique\">Confusion, agitation</span> — un <span class=\"kw-alerte\">coma</span> fait suspecter un autre mécanisme (<span class=\"kw-clinique\">méningo-encéphalite</span>, hématome)</li><li><span class=\"kw-clinique\">Oligurie &lt; 0,5 mL/kg/h</span> ou <span class=\"kw-chiffre\">&lt; 500 mL/jour</span></li><li><span class=\"kw-bio\">Hyperlactatémie &gt; 2 mmol/L</span> + <span class=\"kw-bio\">acidose métabolique</span> (corrélées à la gravité)</li><li><span class=\"kw-alerte\">Choc hémorragique</span> : <span class=\"kw-alerte\">bradycardie paradoxale</span> ou absence de <span class=\"kw-clinique\">tachycardie</span> = alerte gravissime (phase 2, perte de <span class=\"kw-chiffre\">30-50 %</span> de la <span class=\"kw-clinique\">masse</span> sanguine, précède l'<span class=\"kw-alerte\">arrêt cardiaque</span>)</li><li><span class=\"kw-alerte\">Triade létale du choc hémorragique</span> : <span class=\"kw-clinique\">hypothermie</span> <span class=\"kw-chiffre\">&lt; 35 °C</span>, acidose <span class=\"kw-chiffre\">pH &lt; 7,2</span>, coagulopathie <span class=\"kw-chiffre\">INR &gt; 1,5</span></li></ul>","principes":"<p><strong>Bilan <span class=\"kw-ttt\">biologique</span> d'<span class=\"kw-alerte\">urgence</span></strong></p><ul><li>Systématiques : <span class=\"kw-bio\">lactatémie</span> + <span class=\"kw-bio\">gaz du sang</span> (diagnostic <span class=\"kw-ttt\">biologique</span> + gravité)</li><li><span class=\"kw-bio\">NFS-plaquettes</span>, <span class=\"kw-bio\">hémostase</span> (<span class=\"kw-bio\">TP</span>, <span class=\"kw-bio\">TCA</span>, <span class=\"kw-bio\">fibrinogène</span> — <span class=\"kw-alerte\">CIVD</span>), <span class=\"kw-bio\">bilan hépatique</span>, <span class=\"kw-bio\">ionogramme</span>, <span class=\"kw-bio\">créatininémie</span>, <span class=\"kw-bio\">urée</span></li><li>Étiologique selon orientation : <span class=\"kw-bio\">ECG</span>, <span class=\"kw-imagerie\">RXT</span>, <span class=\"kw-bio\">hémocultures</span>, groupe ABO-Rhésus</li><li><span class=\"kw-alerte\">Choc</span> <span class=\"kw-etio\">hémorragique</span> : <span class=\"kw-bio\">calcémie ionisée</span>, <span class=\"kw-bio\">groupage + RAI</span> ; l'<span class=\"kw-bio\">Hb peut être faussement normale</span> à la phase initiale</li></ul><p><strong>Mesures communes (<span class=\"kw-alerte\">réanimation</span> hémodynamique)</strong></p><ul><li><span class=\"kw-ttt\">Oxygénothérapie</span> : masque facial <span class=\"kw-chiffre\">10 L/min</span> ou masque à haute concentration <span class=\"kw-chiffre\">≥ 15 L/min</span> (ne corr<span class=\"kw-chiffre\">ige</span> pas le <span class=\"kw-alerte\">choc</span>, prévient l'hypoxémie)</li><li><span class=\"kw-ttt\">Expansion volémique</span> : cristalloïdes (<span class=\"kw-ttt\">Ringer Lactate</span> ou <span class=\"kw-ttt\">NaCl 0,9 %</span>) jusqu'à <span class=\"kw-chiffre\">30 mL/kg</span> (<span class=\"kw-chiffre\">20 mL/kg</span> enfant) pour <span class=\"kw-chiffre\">PAM ≥ 65 mmHg</span> — sauf <span class=\"kw-alerte\">choc</span> obstructif/cardiogénique sans hypovolémie (risque d'<span class=\"kw-alerte\">OAP</span>)</li><li><span class=\"kw-ttt\">Catécholamines</span> si <span class=\"kw-chiffre\">PAM &lt; 65 mmHg</span> malgré remplissage ou <span class=\"kw-chiffre\">PAD &lt; 40 mmHg</span> : en continu à la seringue électrique sur <span class=\"kw-ttt\">VVC</span> (débutables sur VVP en attendant)</li><li><span class=\"kw-ttt\">Noradrénaline</span> en <span class=\"kw-chiffre\">1ère intention</span> (α1) ; <span class=\"kw-ttt\">adrénaline</span> si <span class=\"kw-alerte\">choc</span> réfractaire ; <span class=\"kw-ttt\">dobutamine</span> (β1) si index cardiaque <span class=\"kw-chiffre\">&lt; 2,5 L/min/m²</span></li><li><span class=\"kw-ttt\">Hémisuccinate d'hydrocortisone</span> si doses élevées/croissantes d'amines (insuffisance surrénalienne relative)</li><li><span class=\"kw-ttt\">Bicarbonates</span> / <span class=\"kw-ttt\">épuration extra-rénale</span> si acidose sévère (fonction cardiaque déprimée pour <span class=\"kw-chiffre\">pH &lt; 7,00</span>)</li></ul><p><strong><span class=\"kw-alerte\">Choc</span> <span class=\"kw-etio\">hémorragique</span> — hémostase</strong></p><ul><li><strong>Objectif tensionnel permissif</strong> avant contrôle : <span class=\"kw-chiffre\">PAS 80-90 mmHg</span> / <span class=\"kw-chiffre\">PAM 60-65 mmHg</span> ; si <span class=\"kw-etio\">trauma crânien grave (Glasgow ≤ 8)</span> ou médullaire : <span class=\"kw-chiffre\">PAM ≥ 80 mmHg</span></li><li><span class=\"kw-ttt\">Remplissage</span> cristalloïdes <span class=\"kw-chiffre\">limité à 1 L</span> (éviter l'hémodilution) ; <span class=\"kw-ttt\">noradrénaline</span> si <span class=\"kw-chiffre\">PAS ≤ 80 mmHg</span> malgré<span class=\"kw-chiffre\"> 1000-1500 mL</span> ; proscrire <span class=\"kw-clinique\">les</span> solutés glucosés/hypotoniques</li><li><span class=\"kw-ttt\">Contrôle du saignement</span> (priorité) : compression, <span class=\"kw-ttt\">garrot</span> (noter l'heure), <span class=\"kw-ttt\">chirurgie</span>, <span class=\"kw-imagerie\">endoscopie</span>, radio-embolisation</li><li><span class=\"kw-ttt\">Acide tranexamique</span> (anti-fibrinolytique) <span class=\"kw-chiffre\">1 g</span> dès que possible puis <span class=\"kw-chiffre\">1 g sur 8 h</span></li><li>Lutte contre l'<span class=\"kw-alerte\">hypothermie</span> (réchauffement patient + perfusions) ; correction de l'<span class=\"kw-bio\">hypocalcémie</span> par <span class=\"kw-ttt\">chlorure de calcium IV</span> (cible calcium ionisé <span class=\"kw-chiffre\">&gt; 0,9 mmol/L</span> ; citrate des poches = chélateur)</li><li><span class=\"kw-ci\">CCP contre-indiqués</span> chez <span class=\"kw-clinique\">les</span> patients non traités par <span class=\"kw-ttt\">AVK</span></li></ul><p><strong><span class=\"kw-alerte\">Choc</span> <span class=\"kw-etio\">hémorragique</span> — transfusion (annale)</strong></p><ul><li><span class=\"kw-bio\">RAI indispensable</span> avant toute transfusion, même en <span class=\"kw-alerte\">urgence</span></li><li><strong><span class=\"kw-etio\">UV</span> immédiate (sans délai)</strong> : <span class=\"kw-ttt\">CGR O-</span> chez la femme avant la ménopause, <span class=\"kw-ttt\">CGR O+</span> sinon ; <strong>UV (&lt;<span class=\"kw-chiffre\"> 30 min</span>)</strong> : CGR O compatible RH-Kell ; <strong>UR (<span class=\"kw-chiffre\">2-3 h</span>)</strong> : compatible ABO RH-Kell</li><li><span class=\"kw-ttt\">CGR</span> : pas de seuil fixe, cible <span class=\"kw-chiffre\">Hb 7-9 g/dL</span> (digestif/cirrhose <span class=\"kw-chiffre\">7-8</span>, coronaropathie sévère <span class=\"kw-chiffre\">9-10</span>, neurotraumatisme <span class=\"kw-chiffre\">&gt; 10 g/dL</span>)</li><li><span class=\"kw-ttt\">PFC</span> précoce, ratio <span class=\"kw-chiffre\">PFC/CGR 1/2 à 1/1</span> ; objectif <span class=\"kw-chiffre\">TP &gt; 40 %</span> (neurotrauma <span class=\"kw-chiffre\">&gt; 50-60 %</span>)</li><li><span class=\"kw-ttt\">Fibrinogène</span> en parallèle (quasi-absent des PFC), dose initiale <span class=\"kw-chiffre\">3 g</span> (<span class=\"kw-chiffre\">70 kg</span>) ; objectif <span class=\"kw-chiffre\">&gt; 1,5 g/L</span></li><li><span class=\"kw-ttt\">Concentrés plaquettaires</span> seulement une fois la numération connue, ratio <span class=\"kw-chiffre\">~1/4</span> ; seuil <span class=\"kw-chiffre\">&gt; 50 G/L</span> (<span class=\"kw-chiffre\">&gt; 100 G/L</span> si trauma crânien ou saignement persistant)</li></ul><p><strong><span class=\"kw-alerte\">Choc</span> septique</strong></p><p>Spécifique : <span class=\"kw-ttt\">antibiothérapie</span> (1ère dose <span class=\"kw-chiffre\">&lt; 1 h</span>) ± <span class=\"kw-ttt\">drainage/chirurgie</span> du foyer</p><ul><li><span class=\"kw-ttt\">Remplissage vasculaire</span> + <span class=\"kw-ttt\">noradrénaline</span> ± <span class=\"kw-ttt\">dobutamine</span> si dysfonction cardiaque associée</li></ul><p><strong><span class=\"kw-alerte\">Choc</span> anaphylactique</strong></p><p>Spécifique : <span class=\"kw-ttt\">adrénaline</span> + <span class=\"kw-ttt\">éviction de l'allergène</span></p><ul><li><span class=\"kw-ttt\">Adrénaline IM</span> d'emblée en <span class=\"kw-alerte\">urgence</span> + <span class=\"kw-ttt\">remplissage vasculaire</span></li></ul><p><strong><span class=\"kw-alerte\">Choc</span> cardiogénique (<span class=\"kw-alerte\">SCA</span>)</strong></p><p>Spécifique : <span class=\"kw-ttt\">revascularisation coronaire</span></p><ul><li><span class=\"kw-ci\">Pas de remplissage</span> (sauf <span class=\"kw-clinique\">infarctus</span> du VD) ; <span class=\"kw-ttt\">dobutamine</span> ± <span class=\"kw-ttt\">noradrénaline</span> si <span class=\"kw-clinique\">hypotension</span> persistante ; ± assistance circulatoire veino-artérielle</li></ul><p><strong><span class=\"kw-alerte\">Choc</span> obstructif</strong></p><p>Spécifique : <span class=\"kw-ttt\">thrombolyse</span> si <span class=\"kw-alerte\">embolie pulmonaire</span> ; <span class=\"kw-ttt\">ponction/drainage</span> ou évacuation chirurgicale si <span class=\"kw-alerte\">tamponnade</span></p><ul><li><span class=\"kw-ttt\">Remplissage limité à 500 mL</span> de cristalloïdes + <span class=\"kw-ttt\">noradrénaline</span></li></ul>","suivi":"<p><strong>Objectifs (&lt;<span class=\"kw-chiffre\"> 3 h</span>, idéalement &lt;<span class=\"kw-chiffre\"> 1 h</span>) :</strong> <span class=\"kw-chiffre\">PAM &gt; 65 mmHg</span> ; régression des <span class=\"kw-clinique\">marbrures</span> ; baisse de l'<span class=\"kw-bio\">acidose</span> et de l'<span class=\"kw-bio\">hyperlactatémie</span> ; reprise de la <span class=\"kw-clinique\">diurèse</span><br><strong>Monitorage prioritaire :</strong> <span class=\"kw-bio\">SpO2</span>, scope <span class=\"kw-bio\">ECG</span>, PA non invasive ; <span class=\"kw-ttt\">PA invasive sur cathéter artériel</span> dès l'usage de catécholamines<br><strong>2nd temps :</strong> <span class=\"kw-imagerie\">ETT</span> répétée (référence de l'évaluation hémodynamique) ; <span class=\"kw-ttt\">PVC sur VVC</span> (volémie) ; <span class=\"kw-bio\">gaz du sang</span> + <span class=\"kw-bio\">lactatémie</span> répétés<br><strong><span class=\"kw-alerte\">Choc</span> <span class=\"kw-etio\">hémorragique</span> :</strong> <span class=\"kw-def\">surveillance</span> de l'<span class=\"kw-bio\">Hb</span> au lit (<span class=\"kw-bio\">HemoCue</span>) ; calcium ionisé <span class=\"kw-chiffre\">&gt; 0,9 mmol/L</span> ; lutte contre l'<span class=\"kw-clinique\">hypothermie</span></p>"},"liensGlobaux":[{"href":"https://www.ce-mir.fr/sites/www.ce-mir.fr/files/medias/documents/10.%20%C3%89tats%20de%20choc.pdf","label":"CeMIR — 10. états de choc"},{"href":"https://www.ce-mir.fr/sites/www.ce-mir.fr/files/medias/documents/18.%20Choc%20h%C3%A9morragique.pdf","label":"CeMIR — 18. choc hémorragique"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"État de choc confirmé — Hypotension + hypoperfusion + hyperlactatémie > 2 mmol/L","detail":"<h4>CAT — orientation et traitement selon le type de <span class=\"kw-alerte\">choc</span> — Après <span class=\"kw-clinique\">les</span> mesures immédiates communes : O2, 2 VVP, remplissage, monitorage</h4>","branches":[{"to":"q-orientation","label":"Après mesures immédiates communes","color":"blue"}]},{"id":"q-orientation","kind":"decision","label":"Quelle orientation clinique ? — Quantitatif (↓PP, ↑PAD) vs distributif (↓PAD, ↑PP) ; ETT = examen de référence","branches":[{"to":"t-anaphylaxie","label":"Signes cutanés brutaux + allergène","color":"red"},{"to":"t-hemorragique","label":"Hémorragie / pâleur / jugulaires plates","color":"red"},{"to":"t-septique","label":"Fièvre / foyer infectieux / immunodépression","color":"red"},{"to":"q-cardio-obstr","label":"Turgescence jugulaire (cœur)","color":"amber"},{"to":"t-indetermine","label":"Tableau non évident","color":"blue"}]},{"id":"t-anaphylaxie","kind":"terminal","label":"Choc anaphylactique","color":"red","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Adrénaline IM</span> d'emblée en <span class=\"kw-alerte\">urgence</span></li><li><span class=\"kw-ttt\">Remplissage vasculaire</span></li><li><span class=\"kw-ttt\">Éviction de l'allergène</span></li></ul><h4>Renvoi</h4><ul><li>Item 338 (<span class=\"kw-clinique\">Œdème</span> de Quincke et <span class=\"kw-alerte\">anaphylaxie</span>)</li></ul>"},{"id":"t-hemorragique","kind":"terminal","label":"Choc hémorragique / hypovolémique","color":"red","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Contrôle du saignement</span> : compression, garrot, <span class=\"kw-ttt\">chirurgie</span>, <span class=\"kw-imagerie\">endoscopie</span>, radio-embolisation</li><li><span class=\"kw-ttt\">Remplissage</span> cristalloïdes <span class=\"kw-chiffre\">≤ 1 L</span> + <span class=\"kw-ttt\">produits sanguins</span> (CGR, PFC, <span class=\"kw-bio\">fibrinogène</span>, <span class=\"kw-bio\">plaquettes</span>) ± <span class=\"kw-ttt\">noradrénaline</span> si <span class=\"kw-chiffre\">PAS ≤ 80 mmHg</span></li><li><span class=\"kw-ttt\">Acide tranexamique</span> <span class=\"kw-chiffre\">1 g</span> puis <span class=\"kw-chiffre\">1 g/8 h</span> ; lutte contre la triade létale (<span class=\"kw-clinique\">hypothermie</span>, acidose, coagulopathie)</li></ul><h4>Confirmation</h4><ul><li>Objectif <span class=\"kw-chiffre\">PAS 80-90 mmHg</span> (<span class=\"kw-chiffre\">PAM ≥ 80</span> si trauma crânien grave/médullaire)</li><li>Bilan étiologique : stable → <span class=\"kw-imagerie\">TDM corps entier injecté</span> ; instable → <span class=\"kw-imagerie\">RXT + radio bassin + FAST</span> puis <span class=\"kw-ttt\">chirurgie</span> de damage control</li></ul>"},{"id":"t-septique","kind":"terminal","label":"Choc septique","color":"red","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Remplissage vasculaire</span> + <span class=\"kw-ttt\">noradrénaline</span> ± <span class=\"kw-ttt\">dobutamine</span> si dysfonction cardiaque</li><li><span class=\"kw-ttt\">Antibiothérapie</span> : 1ère dose <span class=\"kw-chiffre\">&lt; 1 h</span> ± <span class=\"kw-ttt\">drainage/chirurgie</span> du foyer</li></ul><h4>Renvoi</h4><ul><li>Item 158 (<span class=\"kw-clinique\">Sepsis</span> et <span class=\"kw-alerte\">choc septique</span>)</li></ul>"},{"id":"q-cardio-obstr","kind":"decision","label":"Crépitants bilatéraux / OAP ? — Turgescence jugulaire présente — distinguer cœur gauche vs obstacle","branches":[{"to":"t-cardiogenique","label":"Crépitants bilatéraux, OAP, FRCV (cœur gauche)","color":"red"},{"to":"t-obstructif","label":"TJ sans OAP (obstacle)","color":"red"}]},{"id":"t-cardiogenique","kind":"terminal","label":"Choc cardiogénique (SCA)","color":"red","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ci\">Pas de remplissage</span> (sauf <span class=\"kw-clinique\">infarctus</span> du VD)</li><li><span class=\"kw-ttt\">Dobutamine</span> ± <span class=\"kw-ttt\">noradrénaline</span> si <span class=\"kw-clinique\">hypotension</span> persistante ; ± assistance circulatoire veino-artérielle</li><li>Spécifique : <span class=\"kw-ttt\">revascularisation coronaire</span></li></ul>"},{"id":"t-obstructif","kind":"terminal","label":"Choc obstructif","color":"red","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Remplissage limité à 500 mL</span> de cristalloïdes + <span class=\"kw-ttt\">noradrénaline</span></li><li>Spécifique : <span class=\"kw-ttt\">thrombolyse</span> si <span class=\"kw-alerte\">embolie pulmonaire</span> ; <span class=\"kw-ttt\">ponction/drainage</span> ou évacuation chirurgicale si <span class=\"kw-alerte\">tamponnade</span></li></ul>"},{"id":"t-indetermine","kind":"terminal","label":"Type indéterminé — caractériser","color":"blue","detail":"<h4>Conduite</h4><ul><li>Caractériser le type de <span class=\"kw-alerte\">choc</span> : <span class=\"kw-imagerie\">ETT</span> répétée (référence), mesure de la <span class=\"kw-bio\">SvcO2</span> et des déterminants de l'oxygénation</li><li>Explorations selon orientation : <span class=\"kw-bio\">ECG</span>, <span class=\"kw-imagerie\">RXT</span>, <span class=\"kw-bio\">hémocultures</span>, <span class=\"kw-imagerie\">angio-TDM</span> si suspicion d'EP</li></ul>"}]},"cards":[{"i":"1f356c890a77","n":332,"o":"332-13","u":"Prise en charge","t":"Connaître les principes de prise en charge du choc anaphylactique (dont la posologie de l’adrénaline par voie intramusculaire)","q":"Quelle est la conduite à tenir en cas de choc anaphylactique réfractaire à l'adrénaline intramusculaire ou chez un patient sous bêtabloquant ?","a":"<p>Si le choc anaphylactique persiste malgré des bolus IM répétés, l'adrénaline est titrée par <strong>voie IV</strong> (bolus de <strong>0,001 mg/kg</strong>) puis poursuivie à la seringue électrique en réanimation. En cas de blocage bêta-adrénergique (patient sous bêtabloquant), le <strong>glucagon</strong> est l'antidote.</p>"},{"i":"45d3cde073f1","n":332,"o":"332-13","u":"Prise en charge","t":"Connaître les principes de prise en charge du choc anaphylactique (dont la posologie de l’adrénaline par voie intramusculaire)","q":"Quelle est la prise en charge thérapeutique initiale du choc anaphylactique et quelle particularité concernant l'adrénaline ?","a":"<p>La prise en charge initiale du choc anaphylactique repose sur l'administration d'<strong>adrénaline d'emblée</strong> et un <strong>remplissage vasculaire</strong>. Il est crucial d'administrer l'adrénaline sans attendre l'échec du remplissage, contrairement aux autres types de choc.</p>"},{"i":"464e2a2b3b82","n":332,"o":"332-13","u":"Prise en charge","t":"Connaître les principes de prise en charge du choc anaphylactique (dont la posologie de l’adrénaline par voie intramusculaire)","q":"Quelle est la posologie de l'adrénaline par voie intramusculaire chez l'adulte et l'enfant dans le cadre du choc anaphylactique ?","a":"<p>L'adrénaline est le traitement de <strong>1<sup>re</sup> intention par voie intramusculaire</strong>, administrée à la face latéro-externe du 1/3 moyen de la cuisse.</p><ul><li><strong>Adultes / enfants &gt; 12 ans ou &gt; 30 kg</strong> : <strong>0,3 à 0,5 mg</strong> (300-500 µg).</li><li><strong>Enfants 15–30 kg</strong> : <strong>0,15 mg</strong> (150 µg).</li><li><strong>Enfants &lt; 15 kg</strong> : environ <strong>0,1 mg / 10 kg</strong> (pas d'AMM, appréciation médicale).</li></ul><p>La dose est de <strong>0,01 mg/kg</strong>, plafonnée à <strong>0,5 mg</strong> par injection, à répéter toutes les <strong>5 à 15 min</strong> si pas d'amélioration.</p>"},{"i":"6c5ab30df528","n":332,"o":"332-13","u":"Prise en charge","t":"Connaître les principes de prise en charge du choc anaphylactique (dont la posologie de l’adrénaline par voie intramusculaire)","q":"Comment définir le choc anaphylactique et quel est son mécanisme physiopathologique principal ?","a":"<p>Le choc anaphylactique est un choc <strong>distributif</strong> se caractérisant par une <strong>vasoplégie</strong> et une <strong>fuite capillaire massive</strong>, d'installation brutale.</p>"}]};